(()=>{'use strict';
const shop=new URLSearchParams(location.search).get('mode')==='shop';document.body.classList.toggle('shop',shop);
const content=document.querySelector('#content'),nav=document.querySelector('#nav');
const products=[{name:'MISS U individual',price:8000,img:'product-individual.jpg'},{name:'MISS U grande',price:16000,img:'product-grande.jpg'}];
const labels=['Envases individuales','Envases grandes','Cucharas'];let stock,orders,history,cart,view,filter='Todos',timer;
const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n);
function reset(){stock=[24,12,36];orders=[{id:'DEMO-01',product:0,qty:2,status:'Nuevo'},{id:'DEMO-02',product:1,qty:1,status:'En preparación',deducted:true},{id:'DEMO-03',product:0,qty:1,status:'Listo',deducted:true}];history=[];cart=[0,0];view=shop?'Inicio':'Stock';filter='Todos';render();}
function say(message){clearTimeout(timer);document.querySelector('#feedback').textContent=message;timer=setTimeout(()=>document.querySelector('#feedback').textContent='',3500);}
function render(){const pages=shop?['Inicio','Productos','Carrito']:['Inicio','Pedidos','Stock'];nav.innerHTML=pages.map(p=>`<button data-view="${p}" aria-pressed="${p===view}">${p}${p==='Carrito'?' ('+cart.reduce((a,b)=>a+b,0)+')':''}</button>`).join('');if(shop)renderShop();else renderControl();}
function renderShop(){if(view==='Inicio'){content.innerHTML=`<div class="hero-demo"><div><small>TIRAMISÚ ARTESANAL · MISS U</small><h1>Tu emergencia dulce tiene nombre.</h1><p>Cremoso, intenso y hecho para que lo extrañes apenas se termina.</p><button class="buy" data-view="Productos">Explorar los productos ↗</button></div><img src="assets/missu/logo-tiramissu.png" alt="MISS U tiramisú artesanal"></div>`;return;}
if(view==='Productos'){content.innerHTML=`<section class="shop-section"><h1>Dos tamaños. Una sola decisión difícil.</h1><p>Probá sumar productos al carrito. Esta demo no genera compras.</p><div class="product-grid">${products.map((p,i)=>`<article class="product"><img src="assets/missu/${p.img}" alt="${p.name}"><div><h2>${p.name}</h2><p>${i?'Para compartir. O para repetir.':'Un antojo, una cuchara, cero explicaciones.'}</p><p class="price">${money(p.price)}</p><button data-add="${i}">Agregar al carrito +</button></div></article>`).join('')}</div></section>`;return;}
const total=cart.reduce((a,q,i)=>a+q*products[i].price,0);content.innerHTML=`<section class="shop-section"><h1>Tu carrito</h1><p class="muted">Pedido de prueba · no se procesa ningún pago.</p><div class="sheet">${total?cart.map((q,i)=>q?`<div class="card"><h2>${products[i].name}</h2><div class="controls"><button data-remove="${i}" aria-label="Quitar una unidad de ${products[i].name}">−</button><strong>${q}</strong><button data-add="${i}" aria-label="Sumar una unidad de ${products[i].name}">+</button><span>${money(q*products[i].price)}</span></div></div>`:'').join('')+`<h2 style="margin-top:25px">Total ${money(total)}</h2><button id="simulate">Simular pedido</button>`:'<div class="empty">Todavía no agregaste productos.<p><button data-view="Productos">Ver productos</button></p></div>'}</div></section>`;}
function renderControl(){if(view==='Stock'){content.innerHTML=`<h1>Stock</h1><p class="muted">Control de envases y cucharas. Probá agregar o descontar unidades.</p><div class="cards">${stock.map((n,i)=>`<article class="card"><h3>${labels[i]}</h3><span style="font-size:32px">${i===2?'🥄':'📦'}</span><div class="count">${n}</div><span class="${n<10?'low':'good'}">${n<10?'¡Stock bajo!':'Stock disponible'}</span><div class="controls"><button data-stock="${i}" data-delta="10" aria-label="Agregar diez ${labels[i]}">+ Agregar 10</button><button data-stock="${i}" data-delta="-1" aria-label="Descontar una unidad de ${labels[i]}">− 1</button></div></article>`).join('')}</div><div class="sheet"><h2>Historial de movimientos</h2>${history.length?`<table><thead><tr><th>Producto</th><th>Movimiento</th><th>Motivo</th></tr></thead><tbody>${history.map(h=>`<tr><td>${h.product}</td><td>${h.delta>0?'+':''}${h.delta}</td><td>${h.reason}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">Hacé un ajuste para ver el movimiento registrado acá.</p>'}</div>`;return;}
if(view==='Inicio'){content.innerHTML=`<h1>Dashboard</h1><p class="muted">Resumen de la demostración · datos ficticios.</p><div class="cards stats">${['Nuevo','En preparación','Listo'].map(s=>`<div class="card"><h3>${s}</h3><div class="count">${orders.filter(o=>o.status===s).length}</div><span>pedidos de ejemplo</span></div>`).join('')}</div><div class="sheet"><h2>Stock rápido</h2>${stock.map((n,i)=>`<p>${labels[i]} <strong>${n} unidades</strong></p>`).join('')}<button data-view="Stock">Ver stock completo →</button></div>`;return;}
const states=['Todos','Nuevo','En preparación','Listo','Entregado'];const shown=orders.filter(o=>filter==='Todos'||o.status===filter);content.innerHTML=`<h1>Pedidos</h1><p class="muted">Probá cambiar un estado. Al preparar un pedido nuevo se descuentan los envases y las cucharas de esta demo.</p><div class="filters">${states.map(s=>`<button data-filter="${s}" aria-pressed="${filter===s}">${s}</button>`).join('')}</div><div class="sheet"><table><thead><tr><th>Pedido</th><th>Producto</th><th>Cantidad</th><th>Estado</th></tr></thead><tbody>${shown.map(o=>`<tr><td>${o.id}</td><td>${products[o.product].name}</td><td>${o.qty}</td><td><select data-order="${o.id}" aria-label="Estado del pedido ${o.id}">${states.slice(1).map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')||'<tr><td colspan="4">No hay pedidos en este estado.</td></tr>'}</tbody></table></div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='reset'){reset();say('Demo reiniciada.');}else if(b.dataset.view){view=b.dataset.view;render();}else if(b.dataset.add!==undefined){cart[Number(b.dataset.add)]++;render();say('Producto agregado al carrito de prueba.');}else if(b.dataset.remove!==undefined){const i=Number(b.dataset.remove);cart[i]=Math.max(0,cart[i]-1);render();}else if(b.id==='simulate'){cart=[0,0];render();say('Simulación completada. No se envió ningún pedido ni se realizó un cobro.');}else if(b.dataset.stock!==undefined){const i=Number(b.dataset.stock),delta=Number(b.dataset.delta);if(stock[i]+delta<0){say('No hay unidades para descontar.');return;}stock[i]+=delta;history.unshift({product:labels[i],delta,reason:'Ajuste de demostración'});render();say('Stock de ejemplo actualizado.');}else if(b.dataset.filter){filter=b.dataset.filter;render();}});
document.addEventListener('change',e=>{if(!e.target.matches('[data-order]'))return;const o=orders.find(x=>x.id===e.target.dataset.order),next=e.target.value;if(next==='En preparación'&&!o.deducted&&o.status==='Nuevo'){if(stock[o.product]<o.qty||stock[2]<o.qty){say('Stock insuficiente. Agregá unidades en Stock.');render();return;}[o.product,2].forEach(i=>{stock[i]-=o.qty;history.unshift({product:labels[i],delta:-o.qty,reason:'Preparación '+o.id});});o.deducted=true;}o.status=next;render();say('Estado de ejemplo actualizado.');});reset();
})();
